import test from 'node:test'
import assert from 'node:assert/strict'
import { readFileSync } from 'node:fs'

import {
  createSave,
  sceneOf,
  choose,
  endingFor,
  endingCell,
  openEnding,
  buildDigest,
  projection,
  matches,
  STAT_KEYS,
  THEME_ORDER
} from '../engine/life.js'

const DATA = JSON.parse(readFileSync(new URL('../data/life.json', import.meta.url), 'utf8'))

function play(state, ids) {
  for (const id of ids) state = choose(state, DATA, id).state
  return state
}

test('data: 9 chapters (6 life + 3 拷问), 70 endings, every option has six effects', () => {
  assert.equal(DATA.chapters.length, 9)
  assert.equal(DATA.chapters.filter((chapter) => chapter.kind === 'question').length, 3)
  assert.equal(DATA.endings.length, 70)
  assert.equal(DATA.endings.filter((ending) => ending.kind === 'special').length, 40)
  assert.equal(DATA.endings.filter((ending) => ending.kind === 'matrix').length, 30)
  assert.equal(DATA.themes.length, 5)
  assert.equal(DATA.costs.length, 7)

  for (const chapter of DATA.chapters) {
    assert.ok(chapter.options.length >= 2, `${chapter.id} has options`)
    for (const option of chapter.options) {
      for (const key of STAT_KEYS) {
        assert.ok(Number.isFinite(option.effects[key]), `${chapter.id}/${option.id} ${key}`)
      }
      if (option.requires !== undefined) {
        assert.equal(typeof option.requires.reason, 'string', `${chapter.id}/${option.id} lock reason`)
      }
    }
  }

  for (const ending of DATA.endings) {
    if (ending.kind === 'special') {
      assert.ok(ending.when, `${ending.id} when`)
      assert.ok(ending.title.length > 0 && ending.text.length > 0)
      assert.ok(ending.hint.length > 0)
      continue
    }
    assert.ok(THEME_ORDER.includes(ending.theme), `${ending.id} theme`)
    assert.equal(ending.id, `${ending.theme}-${ending.cost}`)
    assert.ok(ending.title.length > 0 && ending.text.length > 0)
  }
})

test('new save starts in 2003, age 18, chapter 0, with eight schools and no locks', () => {
  const state = createSave('test')
  const scene = sceneOf(state, DATA)
  assert.equal(scene.year, 2003)
  assert.equal(scene.age, 18)
  assert.equal(scene.chapter, 0)
  assert.equal(scene.options.length, 8)
  assert.equal(scene.options.filter((option) => option.locked).length, 0)
  assert.equal(scene.finished, false)
  assert.equal(scene.era.source, '网吧')
})

test('choosing advances exactly one chapter and clamps stats', () => {
  let state = createSave('walk')
  for (let index = 0; index < DATA.chapters.length; index += 1) {
    const scene = sceneOf(state, DATA)
    const option = scene.options.find((item) => !item.locked)
    assert.ok(option, `chapter ${index} has an open option`)
    state = choose(state, DATA, option.id).state
    for (const key of STAT_KEYS) {
      assert.ok(state.stats[key] >= 0 && state.stats[key] <= 100, `${key} in range`)
    }
  }
  assert.equal(state.finished, true)
  assert.equal(state.chapter, DATA.chapters.length)
  assert.ok(DATA.endings.some((ending) => ending.id === state.endingId))
})

test('all 1101834 paths finish and every one of the 70 endings is reachable', () => {
  const seen = new Map(DATA.endings.map((ending) => [ending.id, 0]))
  let paths = 0

  function walk(state) {
    const scene = sceneOf(state, DATA)
    if (scene.finished === true) {
      paths += 1
      seen.set(scene.ending.id, (seen.get(scene.ending.id) ?? 0) + 1)
      return
    }
    for (const option of scene.options) {
      if (option.locked) continue
      walk(choose(state, DATA, option.id).state)
    }
  }

  walk(createSave('all'))
  assert.equal(paths, 1101834)
  const missing = [...seen].filter(([, count]) => count === 0).map(([id]) => id)
  assert.deepEqual(missing, [])
})

test('your school decides which first jobs exist, and locked paths say why', () => {
  const cs = sceneOf(play(createSave('cs'), ['cs']), DATA)
  const portal = cs.options.find((option) => option.id === 'portal')
  const bank = cs.options.find((option) => option.id === 'bank')
  assert.equal(portal.locked, false)
  assert.equal(bank.locked, true)
  assert.equal(bank.lockReason, '你当年没学金融')

  const art = sceneOf(play(createSave('art'), ['art']), DATA)
  assert.equal(art.options.find((option) => option.id === 'studio').locked, false)
  assert.equal(art.options.find((option) => option.id === 'portal').locked, true)
  assert.throws(() => choose(play(createSave('x'), ['art']), DATA, 'portal'), /没学计算机/)
})

test('the 拷问 answers change what exists at forty-one', () => {
  const plan = ['cs', 'portal', 'yes', 'marry', 'promote', 'poor', 'bigger', 'school']
  const scene = sceneOf(play(createSave('mirror'), plan), DATA)
  const ids = Object.fromEntries(scene.options.map((option) => [option.id, option]))
  assert.equal(ids.school_again.locked, false)
  assert.equal(ids.find_ayuan.locked, true)
  assert.equal(ids.vow.locked, false) // mirror_1 yes → authentic
  assert.equal(ids.peace.locked, true)

  const love = sceneOf(play(createSave('mirror2'), ['cs', 'portal', 'no', 'marry', 'promote', 'poor', 'bigger', 'love']), DATA)
  assert.equal(love.options.find((option) => option.id === 'find_ayuan').locked, false)
  assert.equal(love.options.find((option) => option.id === 'vow').locked, true)
})

test('the fear answers unlock different final options', () => {
  const alone = sceneOf(play(createSave('alone'), ['art', 'studio', 'yes', 'leave', 'study', 'alone', 'stop', 'none']), DATA)
  assert.equal(alone.options.find((option) => option.id === 'find_ayuan').locked, false)
  assert.equal(alone.options.find((option) => option.id === 'crown').locked, true)

  const poor = sceneOf(play(createSave('poor'), ['art', 'studio', 'yes', 'leave', 'study', 'poor', 'stop', 'none']), DATA)
  assert.equal(poor.options.find((option) => option.id === 'crown').locked, false)
  assert.equal(poor.options.find((option) => option.id === 'find_ayuan').locked, true)
})

test('special endings take priority when their life-chain matches', () => {
  const reunion = createSave('reunion')
  reunion.finished = true
  reunion.flags = { reunited: true }
  assert.equal(endingFor(reunion, DATA).id, 'reunion')

  const deploy = createSave('deploy')
  deploy.finished = true
  deploy.flags = { settle: true, coder: true }
  deploy.tags = { city: '深圳', school: '', job: '程序员', partner: '' }
  deploy.stats = { money: 70, health: 55, love: 50, freedom: 50, parents: 50, regret: 20 }
  assert.equal(endingFor(deploy, DATA).id, 'deploy')
})

test('earlier choices change later narration and result copy', () => {
  const coder = sceneOf(play(createSave('coder'), ['cs', 'portal', 'yes']), DATA)
  assert.match(coder.narration, /写代码/)

  const married = play(createSave('married'), ['cs', 'portal', 'yes', 'marry'])
  assert.match(choose(married, DATA, 'promote').option.note, /伴侣/)

  const single = play(createSave('single'), ['cs', 'portal', 'yes', 'single'])
  assert.match(choose(single, DATA, 'promote').option.note, /一个人/)
})

test('repeating a desire compounds later gains', () => {
  const state = createSave('compound')
  state.stats.money = 50
  state.desires.money = 2
  const out = choose(state, DATA, 'finance')
  assert.equal(out.mult, 1.24)
  assert.equal(out.effects.money, 27)

  const self = createSave('compound-self')
  self.desires.self = 2
  const art = choose(self, DATA, 'art')
  assert.equal(art.mult, 1.24)
  assert.equal(art.effects.regret, -7)
})

test('ending is theme x cost, and the open epilogue is assembled from this run', () => {
  const state = createSave('ending')
  state.finished = true
  state.stats = { money: 96, health: 38, love: 40, freedom: 46, parents: 40, regret: 20 }
  state.flags = { ipo: true, bank: true }
  const cell = endingCell(state)
  assert.equal(cell.theme, 'money')
  assert.equal(cell.cost, 'health')
  assert.equal(endingFor(state, DATA).id, 'money-health')

  state.premise = '如果当年去了香港'
  const open = openEnding(state, DATA)
  assert.equal(open.fragments.length, 5)
  assert.equal(open.premise, '如果当年去了香港')
  assert.ok(open.line.includes('身体先亮了红灯'))
  assert.ok(open.line.includes('父母那边'))
})

test('matches supports flags, tags, min/max, desires and any', () => {
  const state = createSave('match')
  state.flags = { cs: true, married: true }
  state.tags.city = '北京'
  state.stats.money = 80
  state.desires.money = 2
  assert.equal(matches(state, { flags: ['cs'], tags: { city: '北京' }, min: { money: 70 }, desires: { money: 2 } }), true)
  assert.equal(matches(state, { any: [{ flags: ['nope'] }, { flags: ['married'] }] }), true)
  assert.equal(matches(state, { notFlags: ['cs'] }), false)
  assert.equal(matches(state, { max: { money: 50 } }), false)
})

test('digest and projection carry the same stats and options', () => {
  const state = createSave('digest')
  state.premise = '如果去了上海'
  const digest = buildDigest(state, DATA)
  const card = projection(state, DATA)
  assert.deepEqual(digest.stats, card.stats)
  assert.equal(digest.options.length, card.options.length)
  assert.equal(card.present, true)
  assert.equal(card.finished, false)
  assert.equal(card.premise, '如果去了上海')
  assert.equal(card.era.hot.length, 3)
})
